import os
import torch


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_2"
    SUBMISSION_DIR = "./submission"

    # Metadata files generated by the metadata script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output paths
    CHECKPOINT_PATH = os.path.join(WORKING_DIR, "checkpoint.pth")
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "model_best.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Model Configuration
    # ==========================================
    MODEL_NAME = "efficientnet_b4"
    NUM_CLASSES = 1010
    PRETRAINED = True

    # EfficientNet-B4 native resolution is 380x380
    IMAGE_SIZE = 380

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    # Batch size tuned for A100 GPU with 380x380 resolution
    BATCH_SIZE = 32
    NUM_EPOCHS = 20

    # Optimizer settings
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    OPTIMIZER_NAME = "AdamW"

    # Scheduler settings (Cosine Annealing)
    SCHEDULER_NAME = "CosineAnnealingLR"
    ETA_MIN = 1e-6

    # Regularization
    LABEL_SMOOTHING = 0.1

    # ==========================================
    # System & Compute
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Using 4 workers to balance I/O with 12 vCPUs available
    NUM_WORKERS = 4

    # ==========================================
    # Debugging / Development
    # ==========================================
    # Set to True to train on a small subset for quick pipeline verification
    DEBUG = False
    DEBUG_SUBSET_SIZE = 1000

    @classmethod
    def setup(cls):
        """
        Ensures necessary directories exist.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)


# Initialize directories upon module import
Config.setup()
